fields.default:
{
  "displayName": "Vendor Invoice Schema",
  "description": "Schema for extracting vendor invoice information",
  "documentPrompt": "This document is a vendor invoice. Extract the invoice information accurately. Do not guess values that are not present.",
  "entityTypes": [
    {
      "type": "invoice_number",
      "displayName": "Invoice Number",
      "description": "Extract the invoice number exactly as printed on the invoice.",
      "valueType": "string",
      "occurrenceType": "REQUIRED_ONCE"
    },
    {
      "type": "invoice_date",
      "displayName": "Invoice Date",
      "description": "Extract the invoice issue date. Do not use the due date.",
      "valueType": "date",
      "occurrenceType": "REQUIRED_ONCE"
    },
    {
      "type": "supplier_name",
      "displayName": "Supplier Name",
      "description": "Extract the legal or business name of the supplier.",
      "valueType": "string",
      "occurrenceType": "REQUIRED_ONCE"
    },
    {
      "type": "supplier_gstin",
      "displayName": "Supplier GSTIN",
      "description": "Extract the supplier GSTIN exactly as printed.",
      "valueType": "string",
      "occurrenceType": "OPTIONAL_ONCE"
    },
    {
      "type": "total_amount",
      "displayName": "Total Amount",
      "description": "Extract the final invoice total including applicable taxes.",
      "valueType": "money",
      "occurrenceType": "REQUIRED_ONCE"
    }
  ]
}
